USE SoporteBT;
GO
CREATE TABLE usuarios(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,nombre nvarchar(100) NOT NULL,apellido nvarchar(100) NOT NULL,usuario nvarchar(50) NOT NULL UNIQUE,email nvarchar(150) NOT NULL UNIQUE,password nvarchar(255) NOT NULL,rol nvarchar(20) NOT NULL DEFAULT 'usuario',activo bit NOT NULL DEFAULT 1,creado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),actualizado_en datetime2 NOT NULL DEFAULT sysutcdatetime());
CREATE TABLE permisos(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,clave nvarchar(80) NOT NULL UNIQUE,nombre nvarchar(120) NOT NULL,descripcion nvarchar(255) NOT NULL,grupo nvarchar(60) NOT NULL,activo bit NOT NULL DEFAULT 1);
CREATE TABLE usuario_permisos(usuario_id int NOT NULL,permiso_id int NOT NULL,PRIMARY KEY(usuario_id,permiso_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(permiso_id) REFERENCES permisos(id) ON DELETE CASCADE);
CREATE TABLE categorias(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,nombre nvarchar(100) NOT NULL UNIQUE,descripcion nvarchar(255) NULL,activo bit NOT NULL DEFAULT 1,creado_en datetime2 NOT NULL DEFAULT sysutcdatetime());
CREATE TABLE equipos(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,codigo nvarchar(50) NOT NULL UNIQUE,tipo nvarchar(80) NOT NULL,marca nvarchar(80) NULL,modelo nvarchar(100) NULL,numero_serie nvarchar(150) NULL,usuario_id int NULL,ubicacion nvarchar(150) NULL,estado nvarchar(30) NOT NULL DEFAULT 'activo',observaciones nvarchar(max) NULL,creado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),actualizado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL);
CREATE UNIQUE INDEX ux_equipos_numero_serie ON equipos(numero_serie) WHERE numero_serie IS NOT NULL;
CREATE TABLE solicitudes(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,codigo nvarchar(20) NOT NULL UNIQUE,usuario_id int NOT NULL,categoria_id int NOT NULL,equipo_id int NULL,tecnico_id int NULL,tecnico_solicitado_id int NULL,titulo nvarchar(180) NOT NULL,descripcion nvarchar(max) NOT NULL,prioridad nvarchar(20) NOT NULL DEFAULT 'media',estado nvarchar(30) NOT NULL DEFAULT 'pendiente',puede_continuar_trabajando bit NOT NULL DEFAULT 1,anydesk_id nvarchar(100) NOT NULL DEFAULT 'PENDIENTE',modalidad_atencion nvarchar(20) NOT NULL DEFAULT 'remoto',fecha_visita_solicitada date NULL,hora_visita_solicitada time NULL,fecha_solicitada date NULL,hora_inicio_solicitada time NULL,hora_fin_solicitada time NULL,fecha_programada date NULL,hora_inicio_programada time NULL,hora_fin_programada time NULL,solucion nvarchar(max) NULL,creado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),actualizado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),resuelto_en datetime2 NULL,cerrado_en datetime2 NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(categoria_id) REFERENCES categorias(id),FOREIGN KEY(equipo_id) REFERENCES equipos(id) ON DELETE SET NULL,FOREIGN KEY(tecnico_id) REFERENCES usuarios(id) ON DELETE SET NULL,FOREIGN KEY(tecnico_solicitado_id) REFERENCES usuarios(id) ON DELETE SET NULL);
CREATE TABLE comentarios(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,solicitud_id int NOT NULL,usuario_id int NOT NULL,comentario nvarchar(max) NOT NULL,creado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),FOREIGN KEY(solicitud_id) REFERENCES solicitudes(id) ON DELETE CASCADE,FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
CREATE TABLE adjuntos(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,solicitud_id int NOT NULL,usuario_id int NOT NULL,nombre_original nvarchar(255) NOT NULL,nombre_archivo nvarchar(255) NOT NULL,ruta nvarchar(500) NOT NULL,tipo_mime nvarchar(100) NULL,tamano bigint NOT NULL,creado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),FOREIGN KEY(solicitud_id) REFERENCES solicitudes(id) ON DELETE CASCADE,FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
CREATE TABLE mensajes_privados(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,solicitud_id int NOT NULL,remitente_id int NOT NULL,destinatario_id int NOT NULL,adjunto_id int NULL,mensaje nvarchar(max) NOT NULL,leido_en datetime2 NULL,creado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),FOREIGN KEY(solicitud_id) REFERENCES solicitudes(id) ON DELETE CASCADE,FOREIGN KEY(remitente_id) REFERENCES usuarios(id),FOREIGN KEY(destinatario_id) REFERENCES usuarios(id),FOREIGN KEY(adjunto_id) REFERENCES adjuntos(id) ON DELETE SET NULL);
CREATE TABLE notificaciones(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,usuario_id int NOT NULL,solicitud_id int NULL,tipo nvarchar(50) NOT NULL,titulo nvarchar(180) NOT NULL,mensaje nvarchar(500) NOT NULL,enlace nvarchar(255) NULL,leida_en datetime2 NULL,creado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(solicitud_id) REFERENCES solicitudes(id) ON DELETE CASCADE);
CREATE TABLE historial_solicitudes(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,solicitud_id int NOT NULL,usuario_id int NOT NULL,estado_anterior nvarchar(30) NULL,estado_nuevo nvarchar(30) NULL,descripcion nvarchar(255) NOT NULL,creado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),FOREIGN KEY(solicitud_id) REFERENCES solicitudes(id) ON DELETE CASCADE,FOREIGN KEY(usuario_id) REFERENCES usuarios(id));


-- Inventario de repuestos/materiales de mantenimiento preventivo y correctivo
CREATE TABLE inventario_mantenimiento(id int IDENTITY(1,1) NOT NULL PRIMARY KEY,codigo nvarchar(80) NOT NULL UNIQUE,nombre nvarchar(160) NOT NULL,descripcion nvarchar(500) NULL,tipo nvarchar(80) NULL,stock_actual int NOT NULL DEFAULT 0,stock_minimo int NOT NULL DEFAULT 0,ubicacion nvarchar(120) NULL,activo bit NOT NULL DEFAULT 1,creado_en datetime2 NOT NULL DEFAULT sysutcdatetime(),actualizado_en datetime2 NOT NULL DEFAULT sysutcdatetime());
